pub fn is_valid_email(s: Str) -> Bool {
  if s.contains(" ") {
    return false
  }
  if s.count("@") != 1 {
    return false
  }
  let parts = s.split("@")
  let local = parts.get_or(0, "")
  let domain = parts.get_or(1, "")
  if local.is_empty() {
    return false
  }
  if not domain.contains(".") {
    return false
  }
  if domain.starts_with(".") or domain.ends_with(".") {
    return false
  }
  if domain.contains("..") {
    return false
  }
  return true
}
